import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.vLhlLNVn.js";const m=JSON.parse('{"title":"Warum startet das Dashboard nicht?","description":"","frontmatter":{"order":1,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/04.fehlerbehebung/01.dashboard-startet-nicht.md"},"headers":[],"relativePath":"de/adapter/esphome/fehlerbehebung/dashboard-startet-nicht.md","filePath":"de/adapter/esphome/fehlerbehebung/dashboard-startet-nicht.md","lastUpdated":null}'),o={name:"de/adapter/esphome/fehlerbehebung/dashboard-startet-nicht.md"};function r(s,e,d,h,l,u){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="warum-startet-das-dashboard-nicht" tabindex="-1">Warum startet das Dashboard nicht? <a class="header-anchor" href="#warum-startet-das-dashboard-nicht" aria-label="Permalink to &quot;Warum startet das Dashboard nicht?&quot;">​</a></h1><p><a id="dashboard-not-start-pillow-esphome"></a></p><h2 id="warum-startet-das-dashboard-nicht-und-was-steht-im-log" tabindex="-1">Warum startet das Dashboard nicht, und was steht im Log? <a class="header-anchor" href="#warum-startet-das-dashboard-nicht-und-was-steht-im-log" aria-label="Permalink to &quot;Warum startet das Dashboard nicht, und was steht im Log?&quot;">​</a></h2><p>Den Grund zeigt das Startprotokoll im ESPHome-Tab, dieselben Meldungen stehen im Log der Instanz. Meist lässt sich die gewählte Version nicht installieren. Dann hilft eine feste ESPHome-Version wie <code>2026.6.5</code> und „Auto Detect“ bei Pillow und Device Builder.</p><table tabindex="0"><thead><tr><th>Meldung</th><th>Bedeutung</th><th>Was du tust</th></tr></thead><tbody><tr><td>„Fatal error starting ESPHomeDashboard“</td><td>Die Installation ist gescheitert, oft wegen einer Versionskombination, die pip nicht auflösen kann.</td><td>Versionen wie unten zurückstellen.</td></tr><tr><td>„ESPHome Dashboard could not be started, &quot;…&quot; is missing in the Python environment“</td><td>Die Python-Umgebung ist unvollständig.</td><td>Python-Umgebung zurücksetzen, siehe <a href="#clear-autopy-cache-if-python">unten</a>.</td></tr><tr><td>„ESPHome Dashboard stopped (exit code …)“</td><td>Das Dashboard ist nach dem Start beendet worden.</td><td>Die <code>[ESPHome - Console]</code>-Zeilen davor nennen den Grund, siehe <a href="#log-only-say-esphome-dashboard">nächster Abschnitt</a>.</td></tr><tr><td>„ESPHome Dashboard container … was not created“</td><td>Docker fehlt, läuft nicht oder das Image ließ sich nicht laden.</td><td>Docker prüfen oder „Docker-Integration verwenden (Beta)“ ausschalten.</td></tr></tbody></table><h3 id="so-gehst-du-vor" tabindex="-1">So gehst du vor <a class="header-anchor" href="#so-gehst-du-vor" aria-label="Permalink to &quot;So gehst du vor&quot;">​</a></h3><ol><li>Öffne die Instanz-Einstellungen, Reiter „ESPHome-Dashboard“.</li><li>Stell „ESPHome Dashboard-Version“ auf <code>2026.6.5</code> oder auf die Version, die zuletzt lief.</li><li>Stell unter „Fortschrittlich“ „Pillow-Version“ und „ESPHome Device Builder-Version“ auf „Auto Detect“.</li><li>Speichere. Die Instanz startet neu und installiert die Versionen.</li><li>Es hat geklappt, wenn das Startprotokoll „ESPHome Dashboard is reachable on port …“ zeigt und das Dashboard im Tab erscheint.</li></ol><p>Startet es dann immer noch nicht, ist oft die Python-Umgebung beschädigt, etwa nach einem abgebrochenen Download: <a href="#clear-autopy-cache-if-python">Wie setze ich die Python-Umgebung zurück?</a></p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/dashboard-nutzen#choose-update-esphome-dashboard-version">Wie wähle oder aktualisiere ich die ESPHome-Dashboard-Version?</a></p><p><a id="about-please-install-pillow-python"></a></p><h2 id="was-tun-bei-please-install-the-pillow-python-package" tabindex="-1">Was tun bei &quot;Please install the pillow python package&quot;? <a class="header-anchor" href="#was-tun-bei-please-install-the-pillow-python-package" aria-label="Permalink to &quot;Was tun bei &quot;Please install the pillow python package&quot;?&quot;">​</a></h2><p>Installier nichts am System. Das Dashboard läuft in der eigenen Python-Umgebung des Adapters und sieht kein Pillow, das du per Paketverwaltung oder pip installierst.</p><ol><li>Öffne im Reiter „ESPHome-Dashboard“ den Bereich „Fortschrittlich“.</li><li>Stell „Pillow-Version“ auf „Auto Detect“. Dann installiert der Adapter das Pillow, das zur gewählten ESPHome-Version passt. Eine feste Version muss zu ESPHome passen, sonst fehlt Pillow.</li><li>Speichere. Die Instanz startet neu und richtet die Umgebung ein.</li><li>Kommt die Meldung weiter, setz die Python-Umgebung zurück.</li></ol><p>Mit „Docker-Integration verwenden (Beta)“ gibt es das Feld nicht, dort bringt das ESPHome-Image Pillow selbst mit.</p><p><strong>Siehe auch:</strong> <a href="#clear-autopy-cache-if-python">Python-Umgebung zurücksetzen</a> · <a href="./../anleitungen/dashboard-nutzen#choose-update-esphome-dashboard-version">Dashboard-Version wählen</a></p><p><a id="log-only-say-esphome-dashboard"></a></p><h2 id="warum-stoppt-das-dashboard-nach-einer-neuen-esphome-version" tabindex="-1">Warum stoppt das Dashboard nach einer neuen ESPHome-Version? <a class="header-anchor" href="#warum-stoppt-das-dashboard-nach-einer-neuen-esphome-version" aria-label="Permalink to &quot;Warum stoppt das Dashboard nach einer neuen ESPHome-Version?&quot;">​</a></h2><p>Die neue Version lässt sich auf deinem System nicht installieren oder starten. Den Grund schreibt der Adapter als Fehler mit <code>[ESPHome - Console]</code> ins Log, direkt vor „ESPHome Dashboard stopped (exit code …)“. Stell die Version zurück, die zuletzt lief.</p><h3 id="so-gehst-du-vor-1" tabindex="-1">So gehst du vor <a class="header-anchor" href="#so-gehst-du-vor-1" aria-label="Permalink to &quot;So gehst du vor&quot;">​</a></h3><ol><li>Öffne die Instanz-Einstellungen, Reiter „ESPHome-Dashboard“.</li><li>Steht bei „ESPHome Dashboard-Version“ „Always last available“ oder die neue Version, trag die Version ein, die zuletzt lief, oder <code>2026.6.5</code>.</li><li>Prüfe unter „Fortschrittlich“, dass „Pillow-Version“ auf „Auto Detect“ steht.</li><li>Speichere. Die Instanz startet neu und installiert die Version. Das dauert einige Minuten.</li><li>Es hat geklappt, wenn danach kein „ESPHome Dashboard stopped“ mehr im Log folgt.</li></ol><p>Normale Meldungen des Dashboards stehen nur auf Protokollstufe „debug“ im Log. Fehler erscheinen immer.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/dashboard-nutzen#choose-update-esphome-dashboard-version">Wie wähle oder aktualisiere ich die ESPHome-Dashboard-Version?</a></p><p><a id="clear-autopy-cache-if-python"></a></p><h2 id="wie-setze-ich-die-python-umgebung-zuruck-wenn-sie-defekt-ist" tabindex="-1">Wie setze ich die Python-Umgebung zurück, wenn sie defekt ist? <a class="header-anchor" href="#wie-setze-ich-die-python-umgebung-zuruck-wenn-sie-defekt-ist" aria-label="Permalink to &quot;Wie setze ich die Python-Umgebung zurück, wenn sie defekt ist?&quot;">​</a></h2><p>Mit „Python-Umgebung zurücksetzen“ löschst du die Python-Umgebung des Dashboards mit ESPHome, Device Builder, Pillow und allem, was dazugehört. Deine YAML-Dateien bleiben erhalten.</p><ol><li>Öffne die Einstellungen der Instanz, Reiter „ESPHome-Dashboard“. Die Instanz muss laufen.</li><li>Klick auf „Python-Umgebung zurücksetzen“ und bestätige.</li><li>Start die Instanz neu. Sie baut die Umgebung beim Start neu auf. Das braucht Internet und dauert einige Minuten.</li></ol><p>Geklappt hat es, wenn im Log <code>Starting ESPHome Dashboard</code> steht und der Tab „ESPHome“ das Dashboard zeigt. Statt des Knopfs kannst du auch <code>esphome.0.info.clearAutopyCache</code> auf <code>true</code> setzen.</p><p>Mit „Docker-Integration verwenden (Beta)“ ist der Knopf ausgeblendet, dort gibt es keine Python-Umgebung.</p><p><a id="about-permission-denied-missing-yaml"></a></p><h2 id="was-tun-bei-permission-denied-oder-fehlendem-yaml-ordner" tabindex="-1">Was tun bei Permission denied oder fehlendem YAML-Ordner? <a class="header-anchor" href="#was-tun-bei-permission-denied-oder-fehlendem-yaml-ordner" aria-label="Permalink to &quot;Was tun bei Permission denied oder fehlendem YAML-Ordner?&quot;">​</a></h2><p>Den Ordner <code>iobroker-data/esphome.&lt;Instanz&gt;</code> legt der Adapter selbst an, beim Start des Dashboards und beim ersten Hochladen einer YAML-Datei. Einen fehlenden Ordner musst du nicht anlegen.</p><p>„Permission denied“ heißt, dass Dateien oder Ordner einem anderen Benutzer gehören als dem, unter dem ioBroker läuft, z. B. nach dem Kopieren als <code>root</code> oder nach einer Wiederherstellung. Die Meldung steht im Startprotokoll im Tab „ESPHome“ oder beim Hochladen im Reiter „YAML-Dateien“.</p><ol><li>Führ in der Konsole <code>iobroker fix</code> aus. Das gibt die Dateien dem ioBroker-Benutzer zurück.</li><li>Start die Instanz neu.</li></ol><p>Setz keine Rechte mit <code>chmod 777</code>.</p>',34)])])}const p=t(o,[["render",r]]);export{m as __pageData,p as default};
